    <View style={styles.filters}>{(["all", "pending", "answered"] as QuestionFilter[]).map((item) => <Pressable key={item} onPress={() => setFilter(item)} style={[styles.chip, filter === item && styles.activeChip]}><Text style={[styles.chipText, filter === item && styles.activeChipText]}>{item === "all" ? "All" : item === "pending" ? `Unanswered (${pending})` : "Answered"}</Text></Pressable>)}</View>
    {questions.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{questions.error ? <Text style={styles.error}>{questions.error.message}</Text> : null}
    {filtered.map((question) => <ModuleCard key={question.id} title={question.productName || "Product question"} meta={`${question.authorName} · ${new Date(question.createdAt).toLocaleDateString("en-BD")}`}><View style={styles.questionTop}><Text style={styles.question}>{question.body}</Text><Text style={[styles.badge, question.status === "answered" ? styles.answered : styles.pending]}>{question.status === "answered" ? "Answered" : "Needs answer"}</Text></View>{question.answers.map((item) => <View key={item.id} style={styles.answerBox}><Text style={styles.answerLabel}>Seller answer</Text><Text style={styles.body}>{item.body}</Text></View>)}{editingId === question.id ? <View style={styles.editor}><TextInput multiline onChangeText={setAnswerText} placeholder="Write a clear, helpful answer..." placeholderTextColor={colors.muted} style={styles.input} value={answerText} /><View style={styles.actions}><Pressable disabled={answer.isPending || answerText.trim().length < 2} onPress={() => answer.mutate({ id: question.id, body: answerText.trim() })} style={[styles.button, answerText.trim().length < 2 && styles.disabled]}><Text style={styles.buttonText}>{answer.isPending ? "Publishing..." : "Publish answer"}</Text></Pressable><Pressable onPress={() => { setEditingId(null); setAnswerText(""); }} style={styles.outline}><Text style={styles.outlineText}>Cancel</Text></Pressable></View>{answer.error ? <Text style={styles.error}>{answer.error.message}</Text> : null}</View> : question.status !== "answered" ? <Pressable onPress={() => setEditingId(question.id)} style={styles.outline}><Text style={styles.outlineText}>Answer this question</Text></Pressable> : null}</ModuleCard>)}
