function Metric({ label, value }: { label: string; value: number }) { return <View style={styles.metric}><Text style={styles.metricValue}>{value}</Text><Text style={styles.muted}>{label}</Text></View>; }
const styles = StyleSheet.create({ metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, metric: { backgroundColor: colors.primarySoft, borderRadius: radius.lg, flex: 1, minWidth: 120, padding: spacing.md }, metricValue: { color: colors.primary, fontSize: 25, fontWeight: "900" }, muted: { color: colors.muted, fontSize: 12 }, body: { color: colors.text, lineHeight: 21 }, filters: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: 12, paddingVertical: 8 }, activeChip: { backgroundColor: colors.primary, borderColor: colors.primary }, chipText: { color: colors.text, fontSize: 12, fontWeight: "800" }, activeChipText: { color: "#fff" }, questionTop: { alignItems: "flex-start", flexDirection: "row", gap: spacing.md, justifyContent: "space-between" }, question: { color: colors.text, flex: 1, fontSize: 16, fontWeight: "800", lineHeight: 23 }, badge: { borderRadius: radius.pill, fontSize: 10, fontWeight: "900", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 5 }, pending: { backgroundColor: "#fff7ed", color: "#c2410c" }, answered: { backgroundColor: "#ecfdf5", color: "#047857" }, answerBox: { backgroundColor: colors.primarySoft, borderLeftColor: colors.primary, borderLeftWidth: 3, borderRadius: radius.md, gap: 5, padding: spacing.md }, answerLabel: { color: colors.primaryDark, fontSize: 11, fontWeight: "900", textTransform: "uppercase" }, editor: { gap: spacing.sm }, input: { borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 100, padding: 12, textAlignVertical: "top" }, actions: { flexDirection: "row", gap: spacing.sm }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 44, paddingHorizontal: spacing.lg }, disabled: { opacity: 0.45 }, buttonText: { color: "#fff", fontWeight: "900" }, outline: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, justifyContent: "center", minHeight: 42, paddingHorizontal: spacing.md }, outlineText: { color: colors.primary, fontWeight: "900" }, error: { color: colors.danger } });
